def calculate_S(N):
    S = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            S += (a * b) // (N + 1)
    return S

def calculate_T(N):
    return (N**3 - N**2 + 2) / 4

N_values = [1, 2, 3, 4, 5]
results = {}

for N in N_values:
    S_N = calculate_S(N)
    T_N = calculate_T(N)
    results[N] = (S_N, T_N)

print("N | S(N) | T(N)")
print("-" * 20)
for N, (S_N, T_N) in results.items():
    print(f"{N} | {S_N} | {T_N}")

def calculate_s_floor(N):
    M = N + 1
    S_floor = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            S_floor += (a * b) // M
    return S_floor

def calculate_target_T(N):
    return (N**3 - N**2 + 2) / 4

results = {}
for N in range(1, 6):
    s_floor = calculate_s_floor(N)
    target = calculate_target_T(N)
    results[N] = {'S_floor': s_floor, 'Target': target, 'Match': s_floor == target}

print("N | S_floor(N) | Target T(N) | Match")
for N, res in results.items():
    print(f"{N} | {res['S_floor']} | {res['Target']} | {res['Match']}")
